    's.understood.3': 'ስእሊ ዘለዎ መምርሒ ኣሎ ድዩ?',
    'c.understood.q': { m: 'ቅድም ኣዋድድ፡ ድሕሪኡ ጠርንፍ።', f: 'ቅድም ኣዋድዲ፡ ድሕሪኡ ጠርንፊ።' },
    'c.understood.a': 'ስለዚ ቅድም ከዋድድ ኣለኒ ማለት ድዩ?',
    'l.keeplearning': { m: 'ምምሃር ቀጽል', f: 'ምምሃር ቀጽሊ' },
