    's.dates.1': 'ካብ ሰኑይ ክሳብ ሓሙስ (ሓሙስ እውን) ክሰርሕ እኽእል።', // nieuw, nog nalezen
    's.dates.2': 'ኣብ ዝመጽእ ሰሙን ኣርባዕተ መዓልቲ እሰርሕ።', // nieuw, nog nalezen
