    'w.zzper': { m: 'ናይ ርእሱ ሰራሕተኛ (ንርእስኻ ትሰርሕ)', f: 'ናይ ርእሳ ሰራሕተኛ (ንርእስኺ ትሰርሒ)' }, // nieuw, nog nalezen
    'w.inburgering': 'ምውህሃድ (ትምህርትን ፈተናታትን ንሓደስቲ መጻእቲ)', // nieuw, nog nalezen
