    's.kids.1': 'ቆልዓይ ሓሚሙ። ክወስዶ ኣለኒ።', // nieuw, nog nalezen
    's.kids.2': 'ናይ ህጹጽ ኩነታት ፍቓድ ክወስድ ይፍቀደለይ ዶ?', // nieuw, nog nalezen
