    'c.body.q': { m: 'ኣበይ እዩ ዘቐንዝወካ?', f: 'ኣበይ እዩ ዘቐንዝወኪ?' }, // nieuw, nog nalezen
    'c.body.a': 'ሕቖይ። ከቢድ ሳጹን ኣልዒለ።', // nieuw, nog nalezen
